package com.bank.fraudpair;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.logging.Logger;

// Finds two transactions summing to a flagged target for National Bank of India.
public class FraudPairFinder {
    private static final Logger log = Logger.getLogger(FraudPairFinder.class.getName());

    // Returns the indices of the first pair summing to target, or empty.
    public Optional<int[]> findPairSummingTo(BigDecimal[] amounts, BigDecimal target) {
        if (amounts == null || amounts.length < 2) return Optional.empty();
        Map<BigDecimal, Integer> seen = new HashMap<>(amounts.length * 2);
        for (int i = 0; i < amounts.length; i++) {
            BigDecimal value = amounts[i].stripTrailingZeros();        // normalise scale
            BigDecimal need = target.subtract(amounts[i]).stripTrailingZeros();
            Integer j = seen.get(need);                                // complement seen?
            if (j != null) {
                final int firstIdx = j, secondIdx = i;
                log.info(() -> "Pair found at indices " + firstIdx + " and " + secondIdx
                        + " summing to Rs." + target);
                return Optional.of(new int[]{j, i});
            }
            seen.put(value, i);                                        // record AFTER the check
        }
        log.info(() -> "No pair sums to Rs." + target);
        return Optional.empty();
    }
}
