package com.bank.fraudpair;

import java.math.BigDecimal;
import java.util.Optional;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: detect a split-into-two pattern hitting a flagged target.
public class FraudPairDemo {
    private static final Logger log = Logger.getLogger(FraudPairDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        FraudPairFinder finder = new FraudPairFinder();

        // Rajesh (SAV2001) transactions; 30000 + 70000 = 100000 flagged target.
        BigDecimal[] amounts = { bd("30000"), bd("5000"), bd("70000.00"), bd("12000") };
        BigDecimal target = bd("100000");

        Optional<int[]> pair = finder.findPairSummingTo(amounts, target);
        pair.ifPresentOrElse(
            p -> log.info(() -> "FRAUD CHECK: indices " + p[0] + "+" + p[1]
                    + " = Rs." + amounts[p[0]] + " + Rs." + amounts[p[1]]),
            () -> log.info("FRAUD CHECK: no suspicious pair")
        );

        // No pair hits 999999.
        Optional<int[]> none = finder.findPairSummingTo(amounts, bd("999999"));
        log.info(() -> "Pair for 999999 present? " + none.isPresent());
    }
}
